fn solve(word: Vec<char>) -> Vec<char> {
    // Helper to check if a character belongs to Set A
    fn is_set_a(c: char) -> bool {
        match c {
            'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M'
          | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z' => true,
            _ => false,
        }
    }

    // If the word is empty (though problem says length ≥ 1), we can consider it valid
    if word.is_empty() {
        return vec!['Y', 'E', 'S'];
    }

    // Determine which set the first character belongs to
    let first_is_a = is_set_a(word[0]);

    // Check that all characters belong to the same set
    for &ch in &word {
        if is_set_a(ch) != first_is_a {
            return vec!['N', 'O'];
        }
    }

    vec!['Y', 'E', 'S']
}